// Shared data-loading helpers for every page. The site reads exactly one
// generated file, site/data/index.json, produced by scripts/build-index.js.
// Nothing here talks to a server beyond that static fetch.

async function loadIndex() {
  const res = await fetch("data/index.json");
  if (!res.ok) {
    throw new Error(
      `Could not load data/index.json (${res.status}). Run "npm run build" first.`
    );
  }
  return res.json();
}

function lookupLabel(list, id) {
  const match = list.find((item) => item.id === id);
  return match ? match.label : id;
}

function skillUrl(slug) {
  return `skill?slug=${encodeURIComponent(slug)}`;
}

function qs(name) {
  return new URLSearchParams(window.location.search).get(name);
}

function renderError(container, err) {
  container.innerHTML = `<p class="empty-state">${err.message}</p>`;
  console.error(err);
}

function escapeHtml(str) {
  return str.replace(
    /[&<>"']/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
  );
}

// Renders a dark terminal-style box with a copy button. Caller must invoke
// bindTerminalCopyButtons(container) after inserting this into the DOM.
function renderTerminal(command, label = "bash") {
  return `
    <div class="terminal">
      <div class="terminal-bar">
        <span class="terminal-label">${escapeHtml(label)}</span>
        <button class="terminal-copy" type="button" data-command="${escapeHtml(command)}">Copy</button>
      </div>
      <pre class="terminal-body"><code>${escapeHtml(command)}</code></pre>
    </div>
  `;
}

// Shared "click to copy, flash a confirmation" behavior for any button
// carrying the text to copy in `data-copy-text`.
function bindCopyButton(btn, copiedLabel = "Copied") {
  btn.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(btn.dataset.copyText);
      const original = btn.textContent;
      btn.textContent = copiedLabel;
      btn.classList.add("copied");
      setTimeout(() => {
        btn.textContent = original;
        btn.classList.remove("copied");
      }, 1500);
    } catch (err) {
      console.error("Copy failed", err);
    }
  });
}

function bindTerminalCopyButtons(container) {
  container.querySelectorAll(".terminal-copy").forEach((btn) => bindCopyButton(btn));
}

const INSTALL_RAW_BASE = "https://raw.githubusercontent.com/Joe-Speed/behavioural-skills/main";
const SITE_BASE_URL = "https://joe-speed.github.io/behavioural-skills";

function shareUrl(slug) {
  return `${SITE_BASE_URL}/s/${encodeURIComponent(slug)}`;
}

// A small button that copies a skill's static, real-metadata share URL
// (site/s/<slug>.html on disk, generated by scripts/build-index.js, served
// extensionless) rather than the skill?slug= URL used for in-site browsing —
// the former unfurls correctly on Slack/Twitter/etc., the latter is
// JS-rendered and won't.
function renderShareLinkButton(slug) {
  return `<button class="share-link-button" type="button" data-copy-text="${escapeHtml(
    shareUrl(slug)
  )}">Copy shareable link</button>`;
}

function bindShareLinkButtons(container) {
  container.querySelectorAll(".share-link-button").forEach((btn) => bindCopyButton(btn, "Link copied"));
}

function renderChangelog(changelog) {
  if (!changelog || changelog.length === 0) {
    return `<p class="empty-state">No version history yet.</p>`;
  }
  const items = changelog
    .slice()
    .reverse()
    .map(
      (c) =>
        `<li><span class="changelog-version">v${escapeHtml(c.version)}</span><span class="changelog-date">${escapeHtml(
          c.date
        )}</span><p>${escapeHtml(c.summary)}</p></li>`
    )
    .join("");
  return `<ul class="changelog-list">${items}</ul>`;
}

// scripts/install.sh takes a comma-separated --name list; scripts/install.ps1
// takes the PowerShell equivalent -Name. Both only support unix-style / pwsh
// invocation respectively, so platform picks which script (and shell) to show.
// With nothing selected yet, names falls back to a placeholder token so the
// terminal always shows a complete (if unrunnable) command rather than
// disappearing.
function buildInstallCommand(slugs, platform) {
  const names = slugs.length > 0 ? slugs.join(",") : "<select-skills>";
  if (platform === "windows") {
    return `iwr -useb ${INSTALL_RAW_BASE}/scripts/install.ps1 -OutFile install.ps1; ./install.ps1 -Target . -Name ${names}`;
  }
  return `curl -sSL ${INSTALL_RAW_BASE}/scripts/install.sh | bash -s -- --target . --name ${names}`;
}

// Renders the install panel shell (platform switch + a slot for the
// terminal). withSelection adds the "Selected: N" summary and chip list used
// by the catalogue's multi-skill picker; skill.html omits it since there's
// only ever one skill in scope.
function renderInstallPanel({ withSelection = false } = {}) {
  return `
    <div class="install-panel">
      <p class="install-eyebrow">Install command</p>
      <p class="install-hint" data-install-hint>Copy, paste, run. Updates as you change platform${withSelection ? " or selection" : ""}.</p>

      <label class="platform-select">
        <span>Platform</span>
        <select class="platform-input">
          <option value="unix">macOS / Linux</option>
          <option value="windows">Windows</option>
        </select>
      </label>

      ${
        withSelection
          ? `<div class="selected-summary">Selected: <strong class="selected-count">0</strong></div>
             <div class="selected-chips"></div>`
          : ""
      }

      <div class="install-terminal-slot"></div>

      <details class="install-advanced">
        <summary>
          <span>Advanced</span>
          <svg class="install-advanced-chevron" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M3.5 6 8 10.5 12.5 6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </summary>
        <div class="install-advanced-body">
          <div class="install-advanced-grid">
            <div>
              <p class="install-advanced-label">Project root</p>
              <div class="install-cd-slot"></div>
            </div>
            <div>
              <p class="install-advanced-label">Verify</p>
              <div class="install-verify-slot"></div>
            </div>
          </div>
          <p class="install-path-note">Selected skills are installed into <code>skills/</code> in your project, unmodified.</p>
        </div>
      </details>
    </div>
  `;
}

// Native <details> snaps open/closed with no transition. Animates the
// body's height instead: on open, set it to 0 then to scrollHeight so the
// browser has a start and end value to transition between; on close, the
// reverse, only flipping the `open` attribute off once the transition ends.
function bindAdvancedUnfurl(details) {
  const summary = details.querySelector("summary");
  const body = details.querySelector(".install-advanced-body");
  if (!summary || !body) return;

  summary.addEventListener("click", (evt) => {
    evt.preventDefault();

    if (details.open) {
      const startHeight = body.getBoundingClientRect().height;
      body.style.height = `${startHeight}px`;
      body.getBoundingClientRect(); // force reflow so the next line transitions
      body.style.height = "0px";
      body.addEventListener(
        "transitionend",
        () => {
          details.open = false;
          body.style.height = "";
        },
        { once: true }
      );
    } else {
      details.open = true;
      const endHeight = body.scrollHeight;
      body.style.height = "0px";
      body.getBoundingClientRect();
      body.style.height = `${endHeight}px`;
      body.addEventListener("transitionend", () => { body.style.height = ""; }, { once: true });
    }
  });
}

// Wires up a panel rendered by renderInstallPanel(). getSlugs() is called on
// every render to get the current skill slug list, so the catalogue can pass
// a closure over its live selection while skill.html passes a fixed one.
// Returns a refresh() function the caller can invoke after the selection
// changes elsewhere (e.g. a checkbox toggle).
function bindInstallPanel(panel, getSlugs) {
  const slot = panel.querySelector(".install-terminal-slot");
  const cdSlot = panel.querySelector(".install-cd-slot");
  const verifySlot = panel.querySelector(".install-verify-slot");
  const select = panel.querySelector(".platform-input");
  const hint = panel.querySelector("[data-install-hint]");
  bindAdvancedUnfurl(panel.querySelector(".install-advanced"));

  function refresh() {
    const slugs = getSlugs();
    const platform = select.value;
    const isWindows = platform === "windows";
    const lang = isWindows ? "powershell" : "bash";

    const command = buildInstallCommand(slugs, platform);
    slot.innerHTML = renderTerminal(command, lang);
    bindTerminalCopyButtons(slot);

    cdSlot.innerHTML = renderTerminal(isWindows ? "cd C:\\path\\to\\your-project" : "cd /path/to/your-project", lang);
    bindTerminalCopyButtons(cdSlot);

    verifySlot.innerHTML = renderTerminal(isWindows ? "dir skills" : "ls skills/", lang);
    bindTerminalCopyButtons(verifySlot);

    if (hint) hint.hidden = slugs.length > 0;
  }

  select.addEventListener("change", refresh);
  refresh();
  return refresh;
}

// Renders the removable chip list in the catalogue's install panel.
function renderSelectedChips(container, selectedSlugs, skillsByslug, onRemove) {
  container.innerHTML = "";
  for (const slug of selectedSlugs) {
    const skill = skillsByslug.get(slug);
    const chip = document.createElement("span");
    chip.className = "chip selected-chip";
    chip.innerHTML = `${escapeHtml(skill ? skill.title : slug)} <button type="button" aria-label="Remove ${escapeHtml(
      skill ? skill.title : slug
    )}">&times;</button>`;
    chip.querySelector("button").addEventListener("click", () => onRemove(slug));
    container.appendChild(chip);
  }
}

// Cmd+K / Ctrl+K command palette: a fuzzy-free (plain substring) search over
// every skill plus a small fixed list of utility pages (What's New, Workflow
// Builder) that don't otherwise sit in the header nav, grouped under
// "Skills" and "Pages" section headers. One overlay is built lazily on
// first use and reused for the rest of the page's life; bindCommandPalette()
// just needs to be called once per page, after that page's data has loaded,
// with the full index object (skills + taxonomy) in scope.
const PALETTE_ICON_SKILL =
  '<svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden="true"><circle cx="8" cy="8" r="6.5" stroke="currentColor" stroke-width="1.4"/><path d="M5.3 8.3 7.1 10 10.7 6" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const PALETTE_ICON_CHANGELOG =
  '<svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden="true"><circle cx="4" cy="3.5" r="1.5" stroke="currentColor" stroke-width="1.3"/><circle cx="4" cy="12.5" r="1.5" stroke="currentColor" stroke-width="1.3"/><circle cx="12" cy="8" r="1.5" stroke="currentColor" stroke-width="1.3"/><path d="M4 5v6" stroke="currentColor" stroke-width="1.3"/><path d="M4 8c0-2 2-3 4-3h2.5" stroke="currentColor" stroke-width="1.3"/></svg>';
const PALETTE_ICON_WORKFLOW =
  '<svg viewBox="0 0 16 16" width="14" height="14" fill="none" aria-hidden="true"><rect x="1" y="6" width="4" height="4" rx="1" stroke="currentColor" stroke-width="1.3"/><rect x="11" y="6" width="4" height="4" rx="1" stroke="currentColor" stroke-width="1.3"/><rect x="6" y="1" width="4" height="4" rx="1" stroke="currentColor" stroke-width="1.3"/><path d="M5 8h6M8 5v1" stroke="currentColor" stroke-width="1.3"/></svg>';

const PALETTE_PAGES = [
  { title: "Workflow Builder", url: "workflow", icon: PALETTE_ICON_WORKFLOW },
  { title: "What's New — version history", url: "whats-new", icon: PALETTE_ICON_CHANGELOG },
];

let paletteState = null;

function buildCommandPalette(data) {
  if (paletteState) return paletteState;

  const items = [
    ...data.skills.map((s) => ({
      title: s.title,
      url: skillUrl(s.slug),
      tag: lookupLabel(data.taxonomy.categories, s.category),
      group: "Skills",
      icon: PALETTE_ICON_SKILL,
      searchText: `${s.title} ${s.description} ${s.category} ${s.stage}`,
    })),
    ...PALETTE_PAGES.map((p) => ({ ...p, tag: "Page", group: "Pages", searchText: p.title })),
  ];

  const overlay = document.createElement("div");
  overlay.className = "command-palette-overlay";
  overlay.hidden = true;
  overlay.innerHTML = `
    <div class="command-palette" role="dialog" aria-modal="true" aria-label="Search skills and pages">
      <input type="text" class="command-palette-input" placeholder="Search skills, or jump to a page…" autocomplete="off" />
      <ul class="command-palette-results"></ul>
      <p class="command-palette-empty" hidden>No matches.</p>
    </div>
  `;
  document.body.appendChild(overlay);

  const input = overlay.querySelector(".command-palette-input");
  const list = overlay.querySelector(".command-palette-results");
  const empty = overlay.querySelector(".command-palette-empty");
  const state = { items, overlay, input, list, empty, activeIndex: 0, matches: [] };

  // Groups render in this fixed order regardless of match order, so the
  // palette never re-shuffles sections while someone is typing.
  const GROUP_ORDER = ["Skills", "Pages"];

  function render(query) {
    const q = query.trim().toLowerCase();
    const found = !q ? items : items.filter((it) => it.searchText.toLowerCase().includes(q));

    const groups = GROUP_ORDER.map((label) => ({ label, items: found.filter((it) => it.group === label) })).filter(
      (g) => g.items.length > 0
    );
    state.matches = groups.flatMap((g) => g.items);
    state.activeIndex = 0;

    let resultIndex = -1;
    list.innerHTML = groups
      .map(
        (group) => `
          <li class="command-palette-group-label">${escapeHtml(group.label)}</li>
          ${group.items
            .map((it) => {
              resultIndex++;
              return `<li class="command-palette-result${resultIndex === 0 ? " active" : ""}" data-url="${escapeHtml(
                it.url
              )}">
                <span class="command-palette-result-main">
                  <span class="command-palette-result-icon">${it.icon}</span>
                  <span class="command-palette-result-title">${escapeHtml(it.title)}</span>
                </span>
                <span class="command-palette-result-tag">${escapeHtml(it.tag)}</span>
              </li>`;
            })
            .join("")}
        `
      )
      .join("");
    empty.hidden = state.matches.length > 0;
  }

  function setActive(index) {
    const els = list.querySelectorAll(".command-palette-result");
    if (els.length === 0) return;
    state.activeIndex = (index + els.length) % els.length;
    els.forEach((el, i) => el.classList.toggle("active", i === state.activeIndex));
    els[state.activeIndex].scrollIntoView({ block: "nearest" });
  }

  function go(url) {
    window.location.href = url;
  }

  input.addEventListener("input", () => render(input.value));
  input.addEventListener("keydown", (evt) => {
    if (evt.key === "ArrowDown") {
      evt.preventDefault();
      setActive(state.activeIndex + 1);
    } else if (evt.key === "ArrowUp") {
      evt.preventDefault();
      setActive(state.activeIndex - 1);
    } else if (evt.key === "Enter") {
      evt.preventDefault();
      const match = state.matches[state.activeIndex];
      if (match) go(match.url);
    } else if (evt.key === "Escape") {
      closeCommandPalette();
    }
  });
  list.addEventListener("click", (evt) => {
    const item = evt.target.closest(".command-palette-result");
    if (item) go(item.dataset.url);
  });
  overlay.addEventListener("click", (evt) => {
    if (evt.target === overlay) closeCommandPalette();
  });

  state.render = render;
  paletteState = state;
  return state;
}

function openCommandPalette() {
  if (!paletteState) return;
  paletteState.overlay.hidden = false;
  paletteState.input.value = "";
  paletteState.render("");
  paletteState.input.focus();
}

function closeCommandPalette() {
  if (!paletteState) return;
  paletteState.overlay.hidden = true;
}

function bindCommandPalette(data) {
  buildCommandPalette(data);

  document.addEventListener("keydown", (evt) => {
    const isOpenShortcut = (evt.metaKey || evt.ctrlKey) && evt.key.toLowerCase() === "k";
    if (isOpenShortcut) {
      evt.preventDefault();
      paletteState.overlay.hidden ? openCommandPalette() : closeCommandPalette();
    } else if (evt.key === "Escape" && !paletteState.overlay.hidden) {
      closeCommandPalette();
    }
  });

  document.querySelectorAll(".command-palette-trigger").forEach((btn) => {
    btn.addEventListener("click", openCommandPalette);
  });
}

function formatStarCount(n) {
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, "") + "k";
  return String(n);
}

// Every page includes a .github-badge in its header; fetch the live star
// count for it. GitHub's REST API allows anonymous CORS reads of public repo
// metadata, so no token or proxy is needed. Fails silently (drops the count,
// keeps the link) on rate-limit or network errors.
async function bindGithubStarBadge() {
  const countEl = document.querySelector(".github-badge-count");
  if (!countEl) return;
  try {
    const res = await fetch("https://api.github.com/repos/Joe-Speed/behavioural-skills");
    if (!res.ok) throw new Error(String(res.status));
    const data = await res.json();
    countEl.textContent = formatStarCount(data.stargazers_count);
  } catch (err) {
    console.error("Could not load GitHub star count", err);
    countEl.remove();
  }
}

bindGithubStarBadge();
